// The relay job purposes — the closed enrich|search vocabulary the store is
// value-agnostic over (CreateRelayJob persists the column verbatim; the relay
// owns the meaning). An enrich job carries a real (row, plugin) pair and gets
// the ledger loop-safety row; a search job has no pair and never touches the
// ledger (D5).
const (
	relayPurposeEnrich = "enrich"
	relayPurposeSearch = "search"
)

// relayedStatus is the ledger status a relay handoff writes: the pair is not
// terminally failed, it is waiting on a client relay. Derivation's existing
// cooldown-skip reads only next_eligible_at, so the status string itself is
// inert vocabulary — the ledger renders it opaquely.
const relayedStatus = "relayed"

// The relay job states the relay itself moves or reads (the closed
// pending|claimed|done|failed set is the caller's — the store is
// value-agnostic): Claim stamps claimed (inside the store's one conditional
// UPDATE), Ingest completes a claimed job to done|failed, and Consult reads
// only done rows. Pending is never named — it is the insert default.
const (
	relayStateDone   = "done"
	relayStateFailed = "failed"
)

// relayGiveUpRounds is the failed-round budget (ruled OQ-3): the THIRD failed
// relay round for a (row, plugin) pair lands terminal exhausted instead of
// re-arming the flat handoff cooldown (spec "Relay give-up after three
// rounds"). The count is CountRelayRounds' stored failed-job count — never an
// in-process counter.
const relayGiveUpRounds = 3

// relayFailurePrefix tags the ledger reason a failed ingest writes (Enqueue
// owns the "<class>: <text>" shape; the ingest side has no class token — the
// client's error text arrives redacted).
const relayFailurePrefix = "relay: "

// Relay zero-value defaults, applied at use (lease/cool). The lease default mirrors
// the MELLIFERA_RELAY_LEASE composition-root default (2m claim handout); the
// cooldown default is the ruled flat handoff cooldown (D5).
const (
	defaultRelayLease = 2 * time.Minute
	defaultRelayCool  = 10 * time.Minute
)

// Relay is the client-relayed-fetch boundary over the relay_jobs store: it
// owns the enqueue/claim/consult/ingest mechanics the enrich chain and the api
// closures ride (D2 — relay lives in enrich, beside fetch, queue, and ledger).
// The struct carries the *store.Store, the lease/cooldown knobs, and the
// library-notify closure (built at the composition root over Queue.Notify —
// the completion wake, D5); nil-safety is decided at the Deps.Relay field
// (D4), never inside Relay: a nil *Relay means relay disabled and today's
// failure behavior is bit-identical.
//
// The zero knobs take their defaults at use (lease/cool); a Relay is otherwise
// stateless — all durability lives in relay_jobs and the enrichment_failures
// ledger, so restarts lose nothing (the relay is the first STORED control
// state since the ledger, on the enrichment_failures precedent).
type Relay struct {
	// Store is the backing store (relay_jobs + the enrichment_failures
	// ledger), set once by the composition root. It is NOT nil-safe — the
	// nil-safety boundary is the Deps.Relay field (D4), never inside Relay.
	Store *store.Store
	// LeaseTTL is the claim handout: how long one client principal owns a
	// claimed job before the claim predicate considers it abandoned (lazy
	// expiry — no sweeper; the folded-into-claim-predicate precedent). Zero
	// or negative → defaultRelayLease at use.
	LeaseTTL time.Duration
	// Cool is the flat 'relayed' ledger cooldown (D5): the handoff keeps the
	// (row, plugin) pair out of derivation for exactly this long — flat, NO
	// doubling, however many relay rounds pile up (the explicitCooldown shape,
	// enrichment 3.4: a retry the operator or the loop didn't choose must never
	// be punished by growth). Zero or negative → defaultRelayCool at use.
	Cool time.Duration
	// Notify is the library-notify closure for the completion wake (D5:
	// ClearFailure + Notify so derivation re-runs the pair into the consult).
	// Never called by Enqueue (no notify at enqueue — the cooldown-skip is the
	// quiet-down); Ingest is its only caller. May be nil.
	Notify func(ctx context.Context, libraryID int64)
}

// lease resolves the claim handout: the composition-root knob when positive,
// the default otherwise (the QueueConfig withDefaults precedent — a zero knob
// never disables, it takes its default).
func (r *Relay) lease() time.Duration {
	if r.LeaseTTL > 0 {
		return r.LeaseTTL
	}
	return defaultRelayLease
}

// cool resolves the flat handoff cooldown the same way.
func (r *Relay) cool() time.Duration {
	if r.Cool > 0 {
		return r.Cool
	}
	return defaultRelayCool
}

// Enqueue inserts one relay job (purpose enrich or search) and — for enrich
// jobs only — writes the relayed ledger row that keeps derivation quiet while
// the job lives (D5): RecordFailure(status="relayed", flat cool, reason =
// class token + redactURLs(errText)). The ledger write is the ONLY write
// beyond the job row, and there is NO notify here: the cooldown-skip is what
// keeps the pair quiet, and derivation needs no wake it will not act on. A
// search job writes no ledger row at all — a search has no (row, plugin) pair
// to cool; its failure path is the search endpoint's existing error.
//
// plan is the whole request plan (primary + extras, positional — task 3.2
// hands it verbatim); class and errText arrive as data (the fetch classifier,
// task 3.1, is upstream of this boundary). The attempts column carries the
// relay round counter under the ledger's own increment discipline (prior row
// +1, first round 1) — the same column Ingest (2.2) increments per failed
// round, never a new counter. A store error is returned wrapped; the caller
// (the chain) decides the soft-fail.
func (r *Relay) Enqueue(ctx context.Context, plan []relay.PlanSpec, purpose, rowID string, libraryID int64, pluginID, class, errText string) error {
	if _, err := r.Store.CreateRelayJob(ctx, relay.RelayJob{
		Purpose:   purpose,
		RowID:     rowID,
		LibraryID: libraryID,
		PluginID:  pluginID,
		Plan:      plan,
	}); err != nil {
		return fmt.Errorf("enrich: relay enqueue %s/%s: %w", rowID, pluginID, err)
	}
	if purpose != relayPurposeEnrich {
		return nil // search: no (row, plugin) pair — no ledger row (D5)
	}
	attempts := 1
	if idx, err := r.failureIndex(ctx); err == nil {
		attempts = priorAttempts(idx, rowID, pluginID) + 1
	}
	reason := fmt.Sprintf("%s: %s", class, redactURLs(errText))
	if err := r.Store.RecordFailure(ctx, rowID, pluginID, relayedStatus, reason, attempts, now().Add(r.cool())); err != nil {
		return fmt.Errorf("enrich: relay enqueue %s/%s (ledger): %w", rowID, pluginID, err)
	}
	return nil
}

// Claim hands the oldest claimable relay job to one client principal: pending,
// or claimed with an expired lease (lazy expiry — the store's ONE conditional
// UPDATE does the exclusive pick, D3; Relay adds no locking of its own). The
// claim is stamped with the principal's hash and a lease_until of now plus the
// configured TTL; the returned RelayJob IS the descriptor the api layer
// projects to the wire (id, purpose, plan — 4.1). Nothing claimable is
// not-found (false, nil error) — the loser of a race and the empty queue read
// identically, and the caller never spins.
func (r *Relay) Claim(ctx context.Context, principalHash string) (relay.RelayJob, bool, error) {
	t := now()
	job, found, err := r.Store.ClaimOldestRelayJob(ctx, principalHash, t, t.Add(r.lease()))
	if err != nil {
		return relay.RelayJob{}, false, fmt.Errorf("enrich: relay claim: %w", err)
	}
	return job, found, nil
}

// Consult is the relay cache read at the fetch path (D4): a done, unconsumed
// enrich job for the (row, plugin) pair whose stored request plan equals the
// current plan — byte-comparison of the rebuilt plan against the stored blob
// (both sides are encoding/json output of the same type, and that marshaler is
// deterministic: struct field order, sorted map keys — so equal plans marshal
// to equal bytes). The hit returns the stored response and marks the job
// consumed (D4: the read that fed Convert); any mismatch, non-done state, or
// missing job is a miss — safe degradation, the caller fetches normally and
// the stale job stays unconsumed. A store read error is an error, not a miss:
// the chain's consumer decides the soft-fail. Candidates scan newest-completed
// first so the freshest plan-matched response wins (the RFC3339Nano TEXT
// ordering carries the store's accepted sub-second truncation skew).
func (r *Relay) Consult(ctx context.Context, rowID, pluginID string, plan []relay.PlanSpec) (relay.RelayResult, bool, error) {
	want, err := json.Marshal(plan)
	if err != nil {
		return relay.RelayResult{}, false, fmt.Errorf("enrich: relay consult %s/%s (plan): %w", rowID, pluginID, err)
	}
	rows, err := r.Store.DB().QueryContext(ctx, `
SELECT id, plan, result FROM relay_jobs
WHERE purpose = ? AND row_id = ? AND plugin_id = ? AND state = ? AND consumed = 0
ORDER BY completed_at DESC, id DESC`,
		relayPurposeEnrich, rowID, pluginID, relayStateDone)
	if err != nil {
		return relay.RelayResult{}, false, fmt.Errorf("enrich: relay consult %s/%s: %w", rowID, pluginID, err)
	}
	defer rows.Close()
	for rows.Next() {
		var (
			id     int64
			plan   []byte
			result []byte
		)
		if err := rows.Scan(&id, &plan, &result); err != nil {
			return relay.RelayResult{}, false, fmt.Errorf("enrich: relay consult %s/%s (scan): %w", rowID, pluginID, err)
		}
		if !bytes.Equal(plan, want) {
			continue // the document drifted — this job is not the current plan's cache
		}
		var out relay.RelayResult
		if err := json.Unmarshal(result, &out); err != nil {
			return relay.RelayResult{}, false, fmt.Errorf("enrich: relay consult %s/%s (result): %w", rowID, pluginID, err)
		}
		if err := r.Store.MarkRelayConsumed(ctx, id); err != nil {
			return relay.RelayResult{}, false, fmt.Errorf("enrich: relay consult %s/%s (consume): %w", rowID, pluginID, err)
		}
		return out, true, nil
	}
	if err := rows.Err(); err != nil {
		return relay.RelayResult{}, false, fmt.Errorf("enrich: relay consult %s/%s: %w", rowID, pluginID, err)
	}
	return relay.RelayResult{}, false, nil
}

// Ingest completes one claimed relay job with its claimant's reported outcome:
// a result carrying an Error is the failed state, otherwise done (the 4.2 wire
// rule — error set, response fields absent, for failed). The store's guard is
// the SAME principal hash and a LIVE lease, applied inside the atomic UPDATE:
// a wrong principal, an expired claim, or an unknown id refuses with a wrapped
// sql.ErrNoRows — the 409 shape upstream — and leaves the row untouched.
//
// A done enrich job is a completion (D5): the pair's ledger row clears
// (reset-on-success) and the library wakes so derivation re-runs the pair into
// the consult. A failed enrich round increments the ledger's attempts column
// (the same column Enqueue increments per handoff — never a new counter);
// the THIRD failed round lands terminal exhausted through the standard
// terminalCooldown doubling schedule instead of re-arming the flat handoff
// cooldown (recordRelayRound). Search-purpose jobs complete but never touch
// the ledger — their consumer is the search poll (5.1).
func (r *Relay) Ingest(ctx context.Context, jobID int64, principalHash string, result relay.RelayResult) error {
	state := relayStateDone
	if result.Error != "" {
		state = relayStateFailed
	}
	if err := r.Store.CompleteRelayJob(ctx, jobID, principalHash, state, result, now()); err != nil {
		return fmt.Errorf("enrich: relay ingest %d: %w", jobID, err)
	}
	meta, err := r.relayJobMeta(ctx, jobID)
	if err != nil {
		return fmt.Errorf("enrich: relay ingest %d: %w", jobID, err)
	}
	if meta.purpose != relayPurposeEnrich {
		return nil // a search has no (row, plugin) pair — no ledger write, no wake (D5)
	}
	if state == relayStateDone {
		if err := r.Store.ClearFailure(ctx, meta.rowID, meta.pluginID); err != nil {
			return fmt.Errorf("enrich: relay ingest %d (clear): %w", jobID, err)
		}
		if r.Notify != nil {
			r.Notify(ctx, meta.libraryID) // the completion wake — the pair re-derives into the consult
		}
		return nil
	}
	return r.recordRelayRound(ctx, jobID, meta, result)
}

// relayJobMeta is a relay job's immutable identity — the columns CreateRelayJob
// inserted once and no transition ever rewrites (claim and complete touch only
// state, the claim stamps, result, and completion), so a read taken AFTER the
// completion is the row's identity at every earlier moment.
type relayJobMeta struct {
	purpose   string
	rowID     string
	libraryID int64
	pluginID  string
}

// relayJobMeta reads that identity by id over the store connection — the S10
// seam (Store.DB: trusted internal consumers run parameterized reads of tables
// the store exposes no read method for; the store keeps Open/Close). The read
// runs only after CompleteRelayJob has ACCEPTED the outcome, so every refused
// ingest (foreign/expired/unknown) short-circuits at the guard and never
// reaches it.
func (r *Relay) relayJobMeta(ctx context.Context, id int64) (relayJobMeta, error) {
	var m relayJobMeta
	err := r.Store.DB().QueryRowContext(ctx,
		"SELECT purpose, row_id, library_id, plugin_id FROM relay_jobs WHERE id = ?", id,
	).Scan(&m.purpose, &m.rowID, &m.libraryID, &m.pluginID)
	if err != nil {
		return relayJobMeta{}, fmt.Errorf("enrich: relay job meta %d: %w", id, err)
	}
	return m, nil
}

// recordRelayRound is the failed-round ledger write (D5, ruled OQ-3). Rounds
// one and two re-arm the FLAT relayed cooldown with the attempts column
// incremented (the pair re-derives after the cool and hands off again); the
// third failed round records terminal exhausted through the STANDARD
// terminalCooldown doubling schedule instead of re-arming the flat handoff
// cooldown. The give-up reads only stored state: the round count from
// CountRelayRounds' failed-job count, the prior attempts from the ledger
// column (the failureIndex read — Enqueue's own increment discipline). The
// schedule is the §4.4 default fill (withDefaults over the zero QueueConfig:
// MaxAttempts 3, ExhaustedCool 7d doubling, CoolCap cap) — the exhausted row is
// indistinguishable from any queue-lane exhaustion and reopens exactly like
// one (explicit refresh or cooldown lapse).
func (r *Relay) recordRelayRound(ctx context.Context, jobID int64, meta relayJobMeta, result relay.RelayResult) error {
	rounds, err := r.Store.CountRelayRounds(ctx, meta.rowID, meta.pluginID)
	if err != nil {
		return fmt.Errorf("enrich: relay ingest %d (rounds): %w", jobID, err)
	}
	idx, err := r.failureIndex(ctx)
	if err != nil {
		return fmt.Errorf("enrich: relay ingest %d (ledger): %w", jobID, err)
	}
	prior := priorAttempts(idx, meta.rowID, meta.pluginID)
	reason := relayFailurePrefix + redactURLs(result.Error)
	if rounds >= relayGiveUpRounds {
		storeAttempts, cool := terminalCooldown(ledgerExhausted, prior, withDefaults(QueueConfig{}))
		if err := r.Store.RecordFailure(ctx, meta.rowID, meta.pluginID, ledgerExhausted, reason, storeAttempts, now().Add(cool)); err != nil {
			return fmt.Errorf("enrich: relay ingest %d (exhausted): %w", jobID, err)
		}
		return nil
	}
	if err := r.Store.RecordFailure(ctx, meta.rowID, meta.pluginID, relayedStatus, reason, prior+1, now().Add(r.cool())); err != nil {
		return fmt.Errorf("enrich: relay ingest %d (re-arm): %w", jobID, err)
	}
	return nil
}

// failureIndex reads the ledger once for the prior-attempts lookup (the
// worker's fetchFailureIndex shape — the ledger is terminal-only and small,
// single-instance MVP). A read error surfaces to the caller, which records
// round 1 rather than guessing at a phantom prior.
func (r *Relay) failureIndex(ctx context.Context) (failureIndex, error) {
	rows, err := r.Store.ListFailures(ctx)
	if err != nil {
		return nil, fmt.Errorf("enrich: relay ledger read: %w", err)
	}
	return buildFailureIndex(rows), nil
}

// urlRe matches an http(s) URL run of non-space text. Error strings wrap URLs
// in quotes (Get "https://…": dial …) and " is not whitespace, so the match
// can carry trailing quote punctuation — trimmed before parsing below.
var urlRe = regexp.MustCompile(`https?://[^\s]+`)

// urlTrailingPunct is the punctuation an error string may glue to a URL's
// end (the Go error idiom `Get "https://…": dial …` puts `":` right after
// it). The run is trimmed to delimit the token and RE-EMITTED after the
// redacted form, so surrounding text survives redaction verbatim.
const urlTrailingPunct = "\"'`>,;)]}.:"

// redactURLs rewrites every credential-bearing URL in text to its redacted
// form, leaving plain URLs readable (an unroutable upstream's URL is exactly
// what the operator needs to see; the KEY is what must never land in a ledger
// reason, a _stages entry, or a log — D6). A URL is credential-bearing when it
// carries userinfo or a query: the query is dropped and marked ?[redacted],
// userinfo is stripped, fragments go with it. A URL-shaped token that will not
// parse is replaced wholesale — never risk leaking what cannot be read. This
// is the one redaction home: ledger reasons (here), _stages/logs (task 3.1).
func redactURLs(text string) string {
	if !strings.Contains(text, "://") {
		return text
	}
	return urlRe.ReplaceAllStringFunc(text, func(raw string) string {
		core := strings.TrimRight(raw, urlTrailingPunct)
		trailing := raw[len(core):]
		u, err := url.Parse(core)
		if err != nil || u.Host == "" {
			return "[redacted]" + trailing
		}
		keyed := u.User != nil || u.RawQuery != ""
		u.User = nil
		u.RawQuery = ""
		u.Fragment = ""
		out := u.String()
		if keyed {
			out += "?[redacted]"
		}
		return out + trailing
	})
}
